#include "powder/demo_plant.hpp"
#include <iostream>
#include <iomanip>
using powder::demo::V;using namespace powder::demo;
V closest(V p,V a,V b,V c){V ab=b-a,ac=c-a,ap=p-a;float d1=dot(ab,ap),d2=dot(ac,ap);if(d1<=0&&d2<=0)return a;V bp=p-b;float d3=dot(ab,bp),d4=dot(ac,bp);if(d3>=0&&d4<=d3)return b;float vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0)return a+ab*(d1/(d1-d3));V cp=p-c;float d5=dot(ab,cp),d6=dot(ac,cp);if(d6>=0&&d5<=d6)return c;float vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0)return a+ac*(d2/(d2-d6));float va=d3*d6-d5*d4;if(va<=0&&d4-d3>=0&&d5-d6>=0)return b+(c-b)*((d4-d3)/((d4-d3)+(d5-d6)));float inv=1/(va+vb+vc);return a+ab*(vb*inv)+ac*(vc*inv);}
float clearance(V p,const std::vector<powder::Grain>&d,int root,float radius){float best=radius;int stack[64],top=0;stack[top++]=root;while(top){int at=stack[--top];auto lo=d[at],hi=d[at+1];if(p.x<lo.x-best||p.x>hi.x+best||p.y<lo.y-best||p.y>hi.y+best||p.z<lo.z-best||p.z>hi.z+best)continue;if(lo.w>=0){stack[top++]=int(lo.w);stack[top++]=int(hi.w);continue;}for(int j=0;j<int(-lo.w);++j){int t=int(hi.w)+j*3;best=std::min(best,length(p-closest(p,xyz(d[t]),xyz(d[t+1]),xyz(d[t+2]))));}}return best;}
int main(int argc,char**argv){try{std::string root=argv[1];auto d=powder::read_plant_data(root+"/SourceAssets/ProcessPlant_20261111_LowPoly/Simulation/runtime.plant");std::ifstream f(argv[2],std::ios::binary);std::uint64_t checked=0,penetrations=0,deep=0;float worst=0;std::cout<<"{\"frames\":[";bool first=true;while(true){double time;unsigned n;f.read(reinterpret_cast<char*>(&time),8);if(!f)break;f.read(reinterpret_cast<char*>(&n),4);if(n!=20000)throw std::runtime_error("bad snapshot count");std::vector<powder::Grain> p(n);f.read(reinterpret_cast<char*>(p.data()),n*sizeof(powder::Grain));if(!f)throw std::runtime_error("truncated snapshot");unsigned hit=0,inside=0;for(auto a:p){V q=xyz(a);float near=clearance(q,d,int(d[0].x),.002f);V local=xyz(d[1])+rotate(q-xyz(d[1]),float(-std::max(0.,time-48)*15*.10471975511966));near=std::min(near,clearance(local,d,int(d[0].y),.002f));if(near<.0019f)++hit;if(near<.001f)++inside;worst=std::max(worst,.002f-near);}checked+=n;penetrations+=hit;deep+=inside;std::cout<<(first?"":",")<<"{\"time\":"<<time<<",\"surface_overlap\":"<<hit<<",\"over_half_radius\":"<<inside<<"}";first=false;}
std::cout<<"],\"samples\":"<<checked<<",\"surface_overlap\":"<<penetrations<<",\"over_half_radius\":"<<deep<<",\"max_penetration_m\":"<<std::setprecision(9)<<worst<<",\"scope\":\"Independent original triangle surface clearance at five-second snapshots; not exhaustive swept-volume proof\"}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
